<?php

declare(strict_types=1);

namespace App\Http;

use App\Auth\UserRepository;
use Sahil\Auth\AuthManager;
use Sahil\Auth\PasswordResetManager;
use Sahil\Contracts\Auth\AuthenticatableContract;
use Sahil\Contracts\Foundation\ApplicationContract;
use Sahil\Contracts\Mail\MailerContract;
use Sahil\Contracts\View\ViewContract;
use Sahil\Http\Request;
use Sahil\Http\Response;
use Sahil\Mail\Message;
use Sahil\Validation\ValidationResult;
use Sahil\Validation\Validator;
use Throwable;

/**
 * Authentication pages generated by `php sahil make:auth`.
 *
 * These handlers are real: sign-in goes through `AuthManager` (rate limiting,
 * rehashing, session-ID rotation), registration writes an account with a
 * hashed password, password reset issues a single-use token through
 * `PasswordResetManager` and mails the link, and the dashboard requires an
 * account. Invalid input re-renders the same page with field `errors` and the
 * submitted `old` values; successful submissions redirect.
 *
 * Run `php sahil migrate` once so the `users` and `password_reset_tokens`
 * tables exist. Reset links are mailed through the configured transport;
 * the default `log` transport only records the attempt (no content), so
 * configure SMTP or a local mail catcher to receive the link.
 */
final class AuthController
{
    public function __construct(
        private readonly ViewContract $views,
        private readonly ApplicationContract $application,
        private readonly AuthManager $auth,
        private readonly PasswordResetManager $reset,
        private readonly UserRepository $users,
        private readonly MailerContract $mail,
    ) {
    }

    public function showLogin(): Response
    {
        if ($this->auth->check()) {
            return Response::redirect('/dashboard', 303);
        }

        return $this->formPage('auth.login');
    }

    public function login(Request $request): Response
    {
        $form = $request->form();
        $email = $this->email($form);

        $result = $this->validator([
            'email' => 'required|email|length:3,190',
            'password' => 'required|string',
        ], [
            'email.required' => 'Enter the email address for your account.',
            'email.email' => 'Enter a valid email address, like you@example.com.',
            'email.length' => 'That email address is too long.',
            'password.required' => 'Enter your password.',
        ])->validate([...$form, 'email' => $email]);

        if ($result->fails()) {
            return $this->formPage('auth.login', $result, $form);
        }

        $credentials = [
            'email' => $email,
            'password' => $this->oldString($form, 'password'),
        ];

        if (!$this->auth->attempt($credentials, isset($form['remember']))) {
            // One generic message: never reveal whether the email exists.
            return $this->formPage('auth.login', $result, $form, null, [
                'email' => 'These credentials do not match our records.',
            ]);
        }

        return Response::redirect('/dashboard', 303);
    }

    public function showRegister(): Response
    {
        if ($this->auth->check()) {
            return Response::redirect('/dashboard', 303);
        }

        return $this->formPage('auth.register');
    }

    public function register(Request $request): Response
    {
        $form = $request->form();
        $email = $this->email($form);

        $result = $this->validator([
            'name' => 'required|string|length:2,80',
            'email' => 'required|email|length:3,190',
            ...$this->passwordRules($form),
            'terms' => 'required',
        ], [
            'name.required' => 'Enter your full name.',
            'name.length' => 'Use between 2 and 80 characters for your name.',
            'email.required' => 'Enter your email address.',
            'email.email' => 'Enter a valid email address, like you@example.com.',
            'email.length' => 'That email address is too long.',
            'password.required' => 'Choose a password.',
            'password.length' => 'Use at least 8 characters for your password.',
            'password_confirmation.required' => 'Repeat your password.',
            'terms.required' => 'Accept the terms to create an account.',
        ])->validate([...$form, 'email' => $email]);

        if ($result->fails()) {
            return $this->formPage('auth.register', $result, $form);
        }

        if ($this->users->exists($email)) {
            return $this->formPage('auth.register', $result, $form, null, [
                'email' => 'An account with that email already exists. Sign in instead.',
            ]);
        }

        try {
            $user = $this->users->create(
                trim($this->oldString($form, 'name')),
                $email,
                $this->oldString($form, 'password'),
            );
        } catch (Throwable) {
            return $this->formPage('auth.register', $result, $form, null, [
                'email' => 'We could not create that account right now. Please try again.',
            ]);
        }

        $this->auth->login($user);

        return Response::redirect('/dashboard', 303);
    }

    public function logout(): Response
    {
        $this->auth->logout();

        return Response::redirect('/login', 303);
    }

    public function showForgotPassword(): Response
    {
        return $this->formPage('auth.forgot-password');
    }

    public function sendResetLink(Request $request): Response
    {
        $form = $request->form();
        $email = $this->email($form);

        $result = $this->validator([
            'email' => 'required|email|length:3,190',
        ], [
            'email.required' => 'Enter the email address for your account.',
            'email.email' => 'Enter a valid email address, like you@example.com.',
            'email.length' => 'That email address is too long.',
        ])->validate([...$form, 'email' => $email]);

        if ($result->fails()) {
            return $this->formPage('auth.forgot-password', $result, $form);
        }

        $token = $this->reset->createToken($email);

        if ($token !== null) {
            try {
                $this->sendResetMail($request, $email, $token);
            } catch (Throwable) {
                return $this->formPage('auth.forgot-password', $result, $form, null, [
                    'email' => 'We could not send the reset email right now. Please try again.',
                ]);
            }
        }

        // Neutral wording: never reveal whether an address is registered.
        return $this->formPage('auth.forgot-password', $result, $form,
            sprintf('If an account exists for %s, a password reset link is on its way.', $email));
    }

    /**
     * @param array<string, string> $params route parameters; `token` comes from
     *                                      the reset link in the mail
     */
    public function showResetPassword(Request $request, array $params = []): Response
    {
        return $this->formPage('auth.reset-password', null, [
            'token' => (string) ($params['token'] ?? ''),
        ]);
    }

    public function resetPassword(Request $request, array $params = []): Response
    {
        $form = $request->form();
        $token = (string) ($params['token'] ?? $form['token'] ?? '');
        $email = $this->email($form);

        $result = $this->validator([
            'token' => 'required|string',
            'email' => 'required|email|length:3,190',
            ...$this->passwordRules($form),
        ], [
            'token.required' => 'This reset link is incomplete. Request a new one.',
            'email.required' => 'Enter the email address for your account.',
            'email.email' => 'Enter a valid email address, like you@example.com.',
            'email.length' => 'That email address is too long.',
            'password.required' => 'Choose a new password.',
            'password.length' => 'Use at least 8 characters for your new password.',
            'password_confirmation.required' => 'Repeat your new password.',
        ])->validate([...$form, 'token' => $token, 'email' => $email]);

        $data = [...$form, 'token' => $token];

        if ($result->fails()) {
            return $this->formPage('auth.reset-password', $result, $data);
        }

        $user = $this->reset->validateToken($token, $email);

        if ($user === null) {
            return $this->formPage('auth.reset-password', $result, $data, null, [
                'token' => 'This password reset link is invalid or has expired. Request a new one.',
            ]);
        }

        try {
            $this->users->updatePassword($user, $this->oldString($form, 'password'));
        } catch (Throwable) {
            return $this->formPage('auth.reset-password', $result, $data, null, [
                'token' => 'We could not save that password right now. Please try again.',
            ]);
        }

        // Single use: every outstanding link for this account stops working.
        $this->reset->deleteTokens($user);

        return $this->formPage('auth.reset-password', null, ['token' => $token],
            'Your password has been reset. Sign in with the new password.');
    }

    public function showDashboard(): Response
    {
        $user = $this->auth->user();
        $name = $this->userAttribute($user, 'name', 'there');
        $email = $this->userAttribute($user, 'email', '');

        return $this->page('pages.dashboard', [
            'user' => [
                'name' => $name,
                'email' => $email,
                'initials' => $this->initials($name),
                'role' => 'Member',
            ],
            ...$this->dashboardData(),
        ]);
    }

    /**
     * Demo content for the dashboard. The signed-in account comes from
     * `AuthManager`; these metrics and rows are placeholders to replace with
     * your own queries.
     *
     * @return array<string, mixed>
     */
    private function dashboardData(): array
    {
        return [
            'stats' => [
                ['label' => 'Revenue', 'value' => '$12,480', 'change' => '+12.4%', 'direction' => 'up', 'hint' => 'vs. last month'],
                ['label' => 'New customers', 'value' => '324', 'change' => '+8.1%', 'direction' => 'up', 'hint' => 'vs. last month'],
                ['label' => 'Active projects', 'value' => '18', 'change' => '+2', 'direction' => 'up', 'hint' => 'since last week'],
                ['label' => 'Churn', 'value' => '1.2%', 'change' => '-0.3%', 'direction' => 'down', 'hint' => 'vs. last month'],
            ],
            'activity' => [
                ['initials' => 'GH', 'name' => 'Grace Hopper', 'email' => 'grace@example.com', 'action' => 'Deployed release 1.4.0 to production', 'when' => '12 minutes ago', 'status' => 'Success', 'tone' => 'success'],
                ['initials' => 'AT', 'name' => 'Alan Turing', 'email' => 'alan@example.com', 'action' => 'Created the “Checkout” project', 'when' => '48 minutes ago', 'status' => 'Success', 'tone' => 'success'],
                ['initials' => 'KL', 'name' => 'Katherine Johnson', 'email' => 'katherine@example.com', 'action' => 'Password reset requested', 'when' => '2 hours ago', 'status' => 'Pending', 'tone' => 'pending'],
                ['initials' => 'ML', 'name' => 'Margaret Hamilton', 'email' => 'margaret@example.com', 'action' => 'Invite to the workspace expired', 'when' => 'Yesterday', 'status' => 'Failed', 'tone' => 'failed'],
                ['initials' => 'TK', 'name' => 'Tim Berners-Lee', 'email' => 'tim@example.com', 'action' => 'Updated billing details', 'when' => '2 days ago', 'status' => 'Success', 'tone' => 'success'],
            ],
            'tasks' => [
                ['label' => 'Review the authentication pages', 'done' => true],
                ['label' => 'Connect the login form to AuthManager', 'done' => true],
                ['label' => 'Send the first password-reset mail', 'done' => false],
                ['label' => 'Invite the rest of the team', 'done' => false],
            ],
        ];
    }

    /**
     * Password rules shared by registration and reset. The confirmation is
     * compared with the submitted password by a closure rule, because the
     * validator has no cross-field rule.
     *
     * @param array<string, string> $form
     *
     * @return array<string, string|array<int, string|\Closure>>
     */
    private function passwordRules(array $form): array
    {
        return [
            'password' => [
                'required',
                'string',
                'length:8,255',
                static function (string $path, mixed $value): ?string {
                    if (!is_string($value)
                        || preg_match('/[A-Za-z]/', $value) !== 1
                        || preg_match('/\d/', $value) !== 1) {
                        return 'Use at least 8 characters, including a letter and a number.';
                    }

                    return null;
                },
            ],
            'password_confirmation' => [
                'required',
                'string',
                static function (string $path, mixed $value) use ($form): ?string {
                    return is_string($value) && $value === ($form['password'] ?? null)
                        ? null
                        : 'The password confirmation does not match.';
                },
            ],
        ];
    }

    /**
     * Mail the single-use reset link. `PasswordResetManager` has already
     * stored the token; the plaintext token exists only in this URL.
     */
    private function sendResetMail(Request $request, string $email, string $token): void
    {
        $scheme = $request->scheme() ?? 'http';
        $host = $request->header('Host') ?? 'localhost';
        $url = sprintf('%s://%s/reset-password/%s', $scheme, $host, rawurlencode($token));
        $minutes = (int) $this->application->config()->get('auth.password_reset.token_expiration', 60);

        $this->mail->send(
            Message::make()
                ->to($email)
                ->subject('Reset your '.$this->application->config()->get('app.name', 'SahilPHP').' password')
                ->text(implode("\n", [
                    'We received a request to reset the password for this address.',
                    '',
                    'Open this link to choose a new password:',
                    $url,
                    '',
                    sprintf('The link expires in %d minutes and can be used once.', $minutes),
                    'If you did not request a reset, no action is needed.',
                ])),
        );
    }

    /**
     * @param array<string, string|array<int, string|\Closure>> $rules
     * @param array<string, string> $messages
     */
    private function validator(array $rules, array $messages): Validator
    {
        return new Validator($rules, $messages);
    }

    /**
     * Render a form page with validation state.
     *
     * @param array<string, string> $form the submitted fields
     * @param array<string, string> $errors extra field errors (e.g. bad credentials)
     * @param array<string, string> $extra additional view data
     */
    private function formPage(
        string $view,
        ?ValidationResult $result = null,
        array $form = [],
        ?string $status = null,
        array $errors = [],
        array $extra = [],
    ): Response {
        $messages = [];

        foreach ($result?->errors() ?? [] as $field => $list) {
            $messages[$field] = $list[0] ?? '';
        }

        return $this->page($view, [
            'errors' => [...$messages, ...$errors],
            'old' => [
                'name' => $this->oldString($form, 'name'),
                'email' => $this->oldString($form, 'email'),
                'token' => $this->oldString($form, 'token'),
                'remember' => isset($form['remember']),
                'terms' => isset($form['terms']),
            ],
            'status' => $status,
            ...$extra,
        ]);
    }

    /**
     * @param array<string, mixed> $form
     */
    private function oldString(array $form, string $key): string
    {
        $value = $form[$key] ?? '';

        return is_string($value) ? $value : '';
    }

    /**
     * @param array<string, mixed> $form
     */
    private function email(array $form): string
    {
        return strtolower(trim($this->oldString($form, 'email')));
    }

    private function userAttribute(?AuthenticatableContract $user, string $key, string $default): string
    {
        if ($user === null) {
            return $default;
        }

        $value = method_exists($user, 'get') ? $user->get($key, $default) : $default;

        return is_string($value) ? $value : $default;
    }

    private function initials(string $name): string
    {
        $parts = preg_split('/\s+/', trim($name)) ?: [];
        $initials = '';

        foreach (array_slice($parts, 0, 2) as $part) {
            $initials .= mb_strtoupper(mb_substr($part, 0, 1));
        }

        return $initials === '' ? '?' : $initials;
    }

    /**
     * @param array<string, mixed> $data
     */
    private function page(string $view, array $data = []): Response
    {
        return Response::html($this->views->render($view, [
            'app_name' => (string) $this->application->config()->get('app.name', 'SahilPHP'),
            'year' => gmdate('Y'),
            // The template language only allows its whitelisted helpers, so the
            // session token is passed in as data rather than called in the view.
            'csrf_token' => csrf_token(),
            ...$data,
        ]));
    }
}
